let runtime: ToolNestModuleContext | undefined
type SecurityConfirmation = { risk_confirmed: true; scan_id: string }

function ModuleShell({ children, title, description, action }: { children: ReactNode; title: string; description: string; action?: ReactNode }) {
  return <main className="tn-python-module"><header className="tn-python-module__header"><div><h1 className="tn-python-module__title">{title}</h1><p className="tn-python-module__description">{description}</p></div>{action}</header>{children}</main>
}

function LoadingState({ text = '正在加载 Python 工具数据…' }: { text?: string }) { return <div className="tn-python-module__panel" role="status"><span className="tn-python-module__spinner" aria-hidden="true" />{text}</div> }
function errorMessage(error: unknown) {
  if (error && typeof error === 'object') {
    const responseData = (error as { response?: { data?: { message?: unknown } } }).response?.data
    if (typeof responseData?.message === 'string' && responseData.message.trim()) return responseData.message
  }
  return error instanceof Error ? error.message : '请稍后重试。'
}
function ErrorState({ error, text }: { error: unknown; text?: string }) { return <div className="tn-python-module__error" role="alert">{text ?? '暂时无法读取 Python 工具数据'}：{errorMessage(error)}</div> }
function Button({ children, pending = false, secondary = false, ...props }: { children: ReactNode; pending?: boolean; secondary?: boolean } & React.ButtonHTMLAttributes<HTMLButtonElement>) { return <button {...props} className={`tn-python-module__button${secondary ? ' tn-python-module__button--secondary' : ''}`} disabled={pending || props.disabled} aria-busy={pending || undefined}>{pending ? <><span className="tn-python-module__spinner" aria-hidden="true" />处理中…</> : children}</button> }
function Field({ label, children, description }: { label: string; children: ReactNode; description?: string }) { return <label className="tn-python-module__field"><span>{label}</span>{children}{description ? <small className="tn-python-module__muted">{description}</small> : null}</label> }
function Status({ value }: { value: string }) { return <span className={`tn-python-module__status tn-python-module__status--${value}`}>{statusText(value)}</span> }
function statusText(value: string) { return ({ success: '成功', failed: '失败', running: '运行中', stopped: '已停止', timeout: '超时', pending: '排队中', enabled: '已启用', disabled: '已停用', ready: '就绪', missing: '未创建', creating: '创建中', high: '高风险', medium: '中风险', low: '低风险', blocked: '已阻断' } as Record<string, string>)[value] ?? value }
function formatTime(value: string | null | undefined) { return value ? new Date(value).toLocaleString() : '—' }
function formatBytes(value: number) { if (value < 1024) return `${value} B`; if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`; return `${(value / 1024 / 1024).toFixed(1)} MB` }
function argsFromText(value: string) { return value.split(/\r?\n/).map((item) => item.trim()).filter(Boolean) }
function textFromArgs(args: string[]) { return args.join('\n') }
function InternalLink({ href, children }: { href: string; children: ReactNode }) { return <a className="tn-python-module__link" href={href} onClick={(event) => { if (!runtime) return; event.preventDefault(); void runtime.router.push(href) }}>{children}</a> }
function Empty({ text }: { text: string }) { return <div className="tn-python-module__empty">{text}</div> }
function Stat({ label, value }: { label: string; value: ReactNode }) { return <div className="tn-python-module__card"><div className="tn-python-module__card-label">{label}</div><div className="tn-python-module__card-value">{value}</div></div> }
function extractSecurity(error: unknown): SecurityScan | null { if (!error || typeof error !== 'object') return null; const response = (error as { response?: { data?: { data?: { security?: SecurityScan } } } }).response; return response?.data?.data?.security ?? null }
function extractProjectImpact(error: unknown): ProjectUpdateResult | null { if (!error || typeof error !== 'object') return null; const response = (error as { response?: { data?: { data?: { impact?: ProjectUpdateResult } } } }).response; return response?.data?.data?.impact ?? null }
function SecurityConfirmation({ scan, checked, onChange }: { scan: SecurityScan | null; checked: boolean; onChange: (value: boolean) => void }) { if (!scan || !['medium', 'high'].includes(scan.risk_level)) return null; return <div className="tn-python-module__security-confirm"><Status value={scan.risk_level} /><span>{scan.message}</span><label><input type="checkbox" checked={checked} onChange={(event) => onChange(event.target.checked)} />我已确认当前扫描结果和代码来源可信</label></div> }
function defaultNotificationConfig(): NotificationConfig { return { notify_on_failure: true, failure_threshold_enabled: true, failure_threshold: 3, notify_on_success: false, notify_on_recovered: false, forward_output_on_success: false, output_mode: 'stdout', max_lines: 100, max_chars: 4000, notify_when_empty_output: false, channels: 'default', custom_channels: [], email_recipients: [] } }
function NotificationFields({ value, onChange, persistent = false }: { value: NotificationConfig; onChange: (value: NotificationConfig) => void; persistent?: boolean }) {
  const patch = (next: Partial<NotificationConfig>) => onChange({ ...value, ...next })
  return <div className="tn-python-module__notification"><h3 className="tn-python-module__panel-title">通知策略</h3><div className="tn-python-module__form-grid"><label className="tn-python-module__checkbox"><input type="checkbox" checked={value.notify_on_failure} onChange={(event) => patch({ notify_on_failure: event.target.checked })} />失败时通知</label><label className="tn-python-module__checkbox"><input type="checkbox" checked={value.notify_on_success} onChange={(event) => patch({ notify_on_success: event.target.checked })} />成功时通知</label><label className="tn-python-module__checkbox"><input type="checkbox" checked={value.notify_on_recovered} onChange={(event) => patch({ notify_on_recovered: event.target.checked })} />恢复成功时通知</label><label className="tn-python-module__checkbox"><input type="checkbox" checked={value.forward_output_on_success} onChange={(event) => patch({ forward_output_on_success: event.target.checked })} />{persistent ? '运行输出转发' : '成功输出转发'}</label></div><div className="tn-python-module__form-grid"><Field label="失败阈值"><div className="tn-python-module__inline-field"><input type="checkbox" checked={value.failure_threshold_enabled} onChange={(event) => patch({ failure_threshold_enabled: event.target.checked })} /><input type="number" min={1} max={100} disabled={!value.failure_threshold_enabled} value={value.failure_threshold} onChange={(event) => patch({ failure_threshold: Math.min(100, Math.max(1, Number(event.target.value) || 1)) })} /></div></Field><Field label="输出内容"><select disabled={!value.forward_output_on_success} value={value.output_mode} onChange={(event) => patch({ output_mode: event.target.value as NotificationConfig['output_mode'] })}><option value="summary">摘要</option><option value="stdout">标准输出</option><option value="stderr">错误输出</option><option value="both">标准输出和错误输出</option></select></Field><Field label="通知通道"><select value={value.channels} onChange={(event) => patch({ channels: event.target.value as NotificationConfig['channels'] })}><option value="default">平台默认</option><option value="custom">自定义</option></select></Field><Field label="自定义通道" description="逗号分隔：站内通知、QQBot、Email、Webhook"><input disabled={value.channels !== 'custom'} value={value.custom_channels.join(', ')} onChange={(event) => patch({ custom_channels: event.target.value.split(',').map((item) => item.trim()).filter(Boolean) })} /></Field><Field label="Email 收件人" description="逗号分隔，平台默认通道可不填"><input value={value.email_recipients.join(', ')} onChange={(event) => patch({ email_recipients: event.target.value.split(',').map((item) => item.trim()).filter(Boolean) })} /></Field></div><label className="tn-python-module__checkbox"><input type="checkbox" checked={value.notify_when_empty_output} onChange={(event) => patch({ notify_when_empty_output: event.target.checked })} />输出为空时也发送成功通知</label></div>
}

function OverviewPage() {
  const query = useQuery({ queryKey: ['python-runner', 'overview'], queryFn: getOverview, staleTime: 5_000, refetchInterval: 10_000 })
  if (query.isPending) return <ModuleShell title="Python 工具" description="管理本地 Python 项目、执行和任务。"><LoadingState /></ModuleShell>
  if (query.isError) return <ModuleShell title="Python 工具" description="管理本地 Python 项目、执行和任务。"><ErrorState error={query.error} /></ModuleShell>
  const { stats, recent_executions: recent, recent_logs: logs } = query.data
  return <ModuleShell title="Python 工具" description="管理本地 Python 项目、执行和任务。" action={<InternalLink href="/modules/python-runner/run">快速运行 →</InternalLink>}><section className="tn-python-module__grid" aria-label="Python 工具统计"><Stat label="运行中" value={stats.running_count} /><Stat label="今日执行" value={stats.today_total} /><Stat label="今日成功" value={stats.today_success} /><Stat label="成功率" value={`${stats.success_rate}%`} /></section><div className="tn-python-module__columns"><section className="tn-python-module__panel"><div className="tn-python-module__toolbar"><h2 className="tn-python-module__panel-title">最近执行</h2><InternalLink href="/modules/python-runner/executions">查看全部</InternalLink></div>{recent.length === 0 ? <Empty text="还没有执行记录。" /> : <ExecutionList items={recent} />}</section><section className="tn-python-module__panel"><h2 className="tn-python-module__panel-title">任务概览</h2><div className="tn-python-module__summary-list"><div><span>启用调度</span><strong>{stats.enabled_schedule_count}</strong></div><div><span>运行中常驻任务</span><strong>{stats.running_persistent_count}</strong></div><div><span>失败常驻任务</span><strong>{stats.failed_persistent_count}</strong></div><div><span>下一次运行</span><strong>{formatTime(stats.next_schedule_time)}</strong></div></div>{logs.length ? <div><h3 className="tn-python-module__panel-title">最近输出</h3><pre className="tn-python-module__output tn-python-module__output--small">{logs.map((item) => `[${item.type}] ${item.content}`).join('\n')}</pre></div> : null}</section></div></ModuleShell>
}

function ExecutionList({ items, onRerun, onDelete, rerunning, deleting }: { items: PythonExecution[]; onRerun?: (id: string) => void; onDelete?: (id: string) => void; rerunning?: string | undefined; deleting?: string | undefined }) { return <ul className="tn-python-module__list">{items.map((item) => <li className="tn-python-module__list-item" key={item.id}><div><InternalLink href={`/modules/python-runner/executions/${item.id}`}>{item.name}</InternalLink><div className="tn-python-module__muted">{item.source_type === 'archive' ? '项目' : '内联'} · {item.entry_file} · {formatTime(item.created_at)}</div></div><div className="tn-python-module__actions"><Status value={item.status} />{onRerun && item.status !== 'running' ? <Button secondary pending={rerunning === item.id} onClick={() => onRerun(item.id)}>重跑</Button> : null}{onDelete && item.status !== 'running' ? <Button secondary pending={deleting === item.id} onClick={() => onDelete(item.id)}>删除</Button> : null}</div></li>)}</ul> }

function RunPage({ initialProjectId }: { initialProjectId?: string | undefined }) {
  const projectsQuery = useQuery({ queryKey: ['python-runner', 'uploads'], queryFn: listUploads, staleTime: 10_000 })
  const [mode, setMode] = useState<'inline' | 'project'>('inline')
  const [code, setCode] = useState("print('Hello ToolNest')\n")
  const [name, setName] = useState('测试脚本')
  const [projectId, setProjectId] = useState(initialProjectId ?? '')
  const [entryFile, setEntryFile] = useState('')
  const [args, setArgs] = useState('')
  const [timeout, setTimeoutValue] = useState(30)
  const [runtimeEnvironment, setRuntimeEnvironment] = useState<CreateExecutionPayload['runtime_environment']>('auto')
  const [security, setSecurity] = useState<SecurityConfirmation | undefined>()
  const [securityChecked, setSecurityChecked] = useState(false)
  const inlineScan = useMutation({ mutationFn: () => scanInline(code), onSuccess: (scan) => { setSecurity(scan.risk_level === 'medium' || scan.risk_level === 'high' ? { risk_confirmed: true, scan_id: scan.scan_id } : undefined); setSecurityChecked(false) } })
  const projectSecurity = useQuery({ queryKey: ['python-runner', 'security', projectId], queryFn: () => getSecurity(projectId), enabled: mode === 'project' && Boolean(projectId) })
  const mutation = useMutation({ mutationFn: () => { const payload = { name: name.trim() || '未命名脚本', args: argsFromText(args), timeout_seconds: timeout, runtime_environment: runtimeEnvironment, ...(securityChecked && security ? { security } : {}) }; return mode === 'inline' ? createExecution({ ...payload, source: { type: 'inline', code } }) : runProject(projectId, entryFile, runtimeEnvironment, payload) }, onSuccess: () => runtime?.notify({ type: 'success', content: 'Python 脚本执行完成。' }), onError: (error) => { const next = extractSecurity(error); if (next) { setSecurity({ risk_confirmed: true, scan_id: next.scan_id }); setSecurityChecked(false) } } })
  const project = projectsQuery.data?.find((item) => item.id === projectId)
  const activeScan = mode === 'inline' ? inlineScan.data ?? null : projectSecurity.data ?? null
  return <ModuleShell title="快速运行" description="运行内联 Python 代码，或从已导入项目选择入口执行。"><section className="tn-python-module__panel"><div className="tn-python-module__segmented"><button className={mode === 'inline' ? 'is-active' : ''} onClick={() => setMode('inline')} type="button">内联脚本</button><button className={mode === 'project' ? 'is-active' : ''} onClick={() => setMode('project')} type="button">项目入口</button></div><Field label="任务名称"><input value={name} onChange={(event) => setName(event.target.value)} /></Field>{mode === 'inline' ? <><Field label="Python 代码"><textarea className="tn-python-module__code" value={code} onChange={(event) => { setCode(event.target.value); setSecurity(undefined) }} /></Field><div className="tn-python-module__actions"><Button secondary pending={inlineScan.isPending} onClick={() => inlineScan.mutate()}>扫描代码</Button></div></> : <><Field label="项目"><select value={projectId} onChange={(event) => { setProjectId(event.target.value); setEntryFile('') }}><option value="">选择项目</option>{(projectsQuery.data ?? []).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></Field><Field label="入口文件"><select value={entryFile} onChange={(event) => setEntryFile(event.target.value)}><option value="">自动选择</option>{(project?.entry_candidates ?? []).map((item) => <option value={item} key={item}>{item}</option>)}</select></Field></>}<div className="tn-python-module__form-grid"><Field label="运行环境"><select value={runtimeEnvironment} onChange={(event) => setRuntimeEnvironment(event.target.value as CreateExecutionPayload['runtime_environment'])}><option value="auto">自动选择项目环境</option><option value="project_venv">项目虚拟环境</option><option value="system">系统 Python</option></select></Field><Field label="超时（秒）"><input type="number" min={1} max={600} value={timeout} onChange={(event) => setTimeoutValue(Math.min(600, Math.max(1, Number(event.target.value) || 1)))} /></Field></div><Field label="命令行参数" description="每行一个参数，控制字符和过长参数会被拒绝。"><textarea className="tn-python-module__code tn-python-module__code--compact" value={args} onChange={(event) => setArgs(event.target.value)} /></Field><SecurityConfirmation scan={activeScan} checked={securityChecked} onChange={setSecurityChecked} /><div className="tn-python-module__actions"><Button pending={mutation.isPending} disabled={!((mode === 'inline' && code.trim()) || (mode === 'project' && projectId))} onClick={() => mutation.mutate()}>运行</Button>{mutation.data ? <span className="tn-python-module__muted">结果：<Status value={mutation.data.status} /> <InternalLink href={`/modules/python-runner/executions/${mutation.data.id}`}>查看详情</InternalLink></span> : null}</div>{mutation.isError ? <ErrorState error={mutation.error} text="脚本运行失败" /> : null}</section></ModuleShell>
}

function ProjectsPage() {
  const query = useQuery({ queryKey: ['python-runner', 'uploads'], queryFn: listUploads, staleTime: 5_000 })
  const inputRef = useRef<HTMLInputElement>(null)
  const updateInputRef = useRef<HTMLInputElement>(null)
  const [name, setName] = useState('')
  const [updateTarget, setUpdateTarget] = useState<ProjectUpload | null>(null)
  const [pendingImpact, setPendingImpact] = useState<{ project: ProjectUpload; file: File; impact: ProjectUpdateResult } | null>(null)
  const upload = useMutation({ mutationFn: (file: File) => uploadProject(file, name), onSuccess: () => { setName(''); void query.refetch(); runtime?.notify({ type: 'success', content: '项目导入完成。' }) } })
  const update = useMutation({ mutationFn: ({ project, file, confirmScheduleImpact = false }: { project: ProjectUpload; file: File; confirmScheduleImpact?: boolean }) => updateUpload(project.id, file, project.name, confirmScheduleImpact), onSuccess: () => { setUpdateTarget(null); setPendingImpact(null); void query.refetch(); runtime?.notify({ type: 'success', content: '项目新版本已上传。' }) }, onError: (error, variables) => { const impact = extractProjectImpact(error); if (impact) setPendingImpact({ project: variables.project, file: variables.file, impact }) } })
  const remove = useMutation({ mutationFn: deleteUpload, onSuccess: () => void query.refetch() })
  if (query.isPending) return <ModuleShell title="项目仓库" description="管理 Python 项目源码、入口和依赖环境。"><LoadingState /></ModuleShell>
  if (query.isError) return <ModuleShell title="项目仓库" description="管理 Python 项目源码、入口和依赖环境。"><ErrorState error={query.error} /></ModuleShell>
  return <ModuleShell title="项目仓库" description="管理 Python 项目源码、入口和依赖环境。"><section className="tn-python-module__panel"><div className="tn-python-module__toolbar"><h2 className="tn-python-module__panel-title">已导入项目</h2><div className="tn-python-module__actions"><input aria-label="项目名称" placeholder="项目名称（可选）" value={name} onChange={(event) => setName(event.target.value)} /><Button pending={upload.isPending} onClick={() => inputRef.current?.click()}>导入 ZIP</Button><input ref={inputRef} hidden type="file" accept=".zip,application/zip" onChange={(event) => { const file = event.target.files?.[0]; if (file) upload.mutate(file); event.target.value = '' }} /><input ref={updateInputRef} hidden type="file" accept=".zip,application/zip" onChange={(event) => { const file = event.target.files?.[0]; if (file && updateTarget) update.mutate({ project: updateTarget, file }); event.target.value = '' }} /></div></div>{upload.isError ? <ErrorState error={upload.error} text="项目导入失败" /> : null}{update.isError && !pendingImpact ? <ErrorState error={update.error} text="项目更新失败" /> : null}{pendingImpact ? <div className="tn-python-module__error" role="alert"><strong>项目更新会影响现有任务</strong><p>{pendingImpact.impact.impacted_tasks.length ? `将刷新 ${pendingImpact.impact.impacted_tasks.length} 个定时或常驻任务的源码引用。` : '检测到任务引用了本项目。'}{pendingImpact.impact.missing_entry_tasks.length ? ` 其中 ${pendingImpact.impact.missing_entry_tasks.length} 个任务的入口文件需要重新确认。` : ''}</p><div className="tn-python-module__actions"><Button pending={update.isPending} onClick={() => update.mutate({ project: pendingImpact.project, file: pendingImpact.file, confirmScheduleImpact: true })}>确认继续更新</Button><Button secondary disabled={update.isPending} onClick={() => setPendingImpact(null)}>取消</Button></div></div> : null}{query.data.length === 0 ? <Empty text="还没有项目，可导入 ZIP 项目。" /> : <ul className="tn-python-module__list">{query.data.map((project) => <li className="tn-python-module__list-item" key={project.id}><div><InternalLink href={`/modules/python-runner/projects/${project.id}`}>{project.name}</InternalLink><div className="tn-python-module__muted">{project.file_count} 个文件 · {formatBytes(project.total_size)} · 入口 {project.entry_candidates[0] ?? '未识别'}</div></div><div className="tn-python-module__actions"><Status value={project.status} /><Button secondary pending={update.isPending && update.variables?.project.id === project.id} onClick={() => { setPendingImpact(null); setUpdateTarget(project); updateInputRef.current?.click() }}>更新</Button><Button secondary pending={remove.isPending && remove.variables === project.id} onClick={() => { if (window.confirm(`确认删除项目「${project.name}」？`)) remove.mutate(project.id) }}>删除</Button></div></li>)}</ul>}</section></ModuleShell>
}

function flattenTree(nodes: ProjectFileNode[]): ProjectFileNode[] { return nodes.flatMap((node) => [node, ...(node.children ? flattenTree(node.children) : [])]) }

function ProjectDetailPage({ projectId }: { projectId: string }) {
  const projectQuery = useQuery({ queryKey: ['python-runner', 'project', projectId], queryFn: () => getUpload(projectId) })
  const securityQuery = useQuery({ queryKey: ['python-runner', 'security', projectId], queryFn: () => getSecurity(projectId), enabled: Boolean(projectQuery.data) })
  const environmentQuery = useQuery({ queryKey: ['python-runner', 'environment', projectId], queryFn: () => getEnvironment(projectId), enabled: Boolean(projectQuery.data), refetchInterval: 5_000 })
  const storageQuery = useQuery({ queryKey: ['python-runner', 'storage', projectId], queryFn: () => getProjectStorage(projectId), enabled: Boolean(projectQuery.data) })
  const configQuery = useQuery({ queryKey: ['python-runner', 'config', projectId], queryFn: () => getProjectConfig(projectId), enabled: Boolean(projectQuery.data) })
  const [selectedFile, setSelectedFile] = useState('')
  const [configContent, setConfigContent] = useState('')
  const [riskConfirmed, setRiskConfirmed] = useState(false)
  const previewQuery = useQuery({ queryKey: ['python-runner', 'preview', projectId, selectedFile], queryFn: () => previewFile(projectId, selectedFile), enabled: Boolean(selectedFile) })
  const scan = useMutation({ mutationFn: () => scanSecurity(projectId), onSuccess: (next) => { setRiskConfirmed(false); void securityQuery.refetch(); if (next.risk_level === 'low') runtime?.notify({ type: 'success', content: '项目安全扫描完成，未发现明显风险。' }) } })
  const create = useMutation({ mutationFn: () => createEnvironment(projectId), onSuccess: () => void environmentQuery.refetch() })
  const install = useMutation({ mutationFn: () => installRequirements(projectId, { confirm_risk: riskConfirmed, scan_id: securityQuery.data?.scan_id }), onSuccess: () => void environmentQuery.refetch() })
  const rebuild = useMutation({ mutationFn: () => rebuildEnvironment(projectId), onSuccess: () => void environmentQuery.refetch() })
  const removeEnvironment = useMutation({ mutationFn: () => deleteEnvironment(projectId), onSuccess: () => void environmentQuery.refetch() })
  const clearData = useMutation({ mutationFn: () => clearProjectData(projectId), onSuccess: () => void environmentQuery.refetch() })
  const rollback = useMutation({ mutationFn: () => rollbackUpload(projectId, true), onSuccess: () => { void projectQuery.refetch(); void securityQuery.refetch(); void environmentQuery.refetch() } })
  const configSave = useMutation({ mutationFn: () => saveProjectConfig(projectId, { content: configContent }), onSuccess: () => void configQuery.refetch() })
  const installLog = useMutation({ mutationFn: () => getInstallLog(projectId) })
  const cleanup = useMutation({ mutationFn: (target: string) => cleanupProject(projectId, target), onSuccess: () => void storageQuery.refetch() })
  useEffect(() => { if (configQuery.data) setConfigContent(configQuery.data.content) }, [configQuery.data])
  if (projectQuery.isPending) return <ModuleShell title="项目详情" description="查看项目源码、风险和运行环境。"><LoadingState /></ModuleShell>
  if (projectQuery.isError) return <ModuleShell title="项目详情" description="查看项目源码、风险和运行环境。"><ErrorState error={projectQuery.error} /></ModuleShell>
  const project = projectQuery.data
  const files = flattenTree(project.file_tree)
  const activeSecurity = extractSecurity(install.error) ?? securityQuery.data
  return <ModuleShell title={project.name} description={`${project.filename} · 最近更新 ${formatTime(project.updated_at)}`} action={<InternalLink href="/modules/python-runner/projects">返回项目仓库</InternalLink>}><section className="tn-python-module__grid"><Stat label="源码文件" value={project.file_count} /><Stat label="源码大小" value={formatBytes(project.total_size)} /><Stat label="安全等级" value={securityQuery.data ? <Status value={securityQuery.data.risk_level} /> : '扫描中'} /><Stat label="环境" value={environmentQuery.data ? <Status value={environmentQuery.data.status} /> : '读取中'} /></section><div className="tn-python-module__columns"><section className="tn-python-module__panel"><div className="tn-python-module__toolbar"><h2 className="tn-python-module__panel-title">入口与文件</h2><InternalLink href={`/modules/python-runner/run?project=${encodeURIComponent(project.id)}`}>去运行 →</InternalLink></div>{project.entry_candidates.length ? <ul className="tn-python-module__list">{project.entry_candidates.map((entry) => <li className="tn-python-module__list-item" key={entry}><button className="tn-python-module__file-button" onClick={() => setSelectedFile(entry)} type="button">{entry}</button><span className="tn-python-module__muted">Python</span></li>)}</ul> : <Empty text="未识别入口文件。" />}<h3 className="tn-python-module__panel-title">文件预览</h3><select value={selectedFile} onChange={(event) => setSelectedFile(event.target.value)}><option value="">选择可预览文件</option>{files.filter((file) => file.type === 'file').map((file) => <option value={file.path} key={file.path}>{file.path}</option>)}</select>{previewQuery.isPending ? <LoadingState text="正在读取文件…" /> : previewQuery.isError ? <ErrorState error={previewQuery.error} text="文件不可预览" /> : previewQuery.data ? <pre className="tn-python-module__output">{previewQuery.data.content}</pre> : <Empty text="选择文件后显示只读预览。" />}<h3 className="tn-python-module__panel-title">依赖文件</h3>{project.dependency_files.length ? <p className="tn-python-module__muted">{project.dependency_files.join('、')}</p> : <Empty text="没有 requirements.txt。" />}</section><section className="tn-python-module__panel"><div className="tn-python-module__toolbar"><h2 className="tn-python-module__panel-title">安全扫描</h2><Button secondary pending={scan.isPending} onClick={() => scan.mutate()}>重新扫描</Button></div>{securityQuery.data ? <><div className="tn-python-module__status-line"><Status value={securityQuery.data.risk_level} /><span className="tn-python-module__muted">{securityQuery.data.message}</span></div>{securityQuery.data.findings.length ? <ul className="tn-python-module__finding-list">{securityQuery.data.findings.slice(0, 50).map((finding) => <li key={finding.id}><Status value={finding.level} /><span>{finding.file}{finding.line ? `:${finding.line}` : ''} · {finding.message}</span></li>)}</ul> : <Empty text="未发现明显风险。" />}</> : <LoadingState />}{activeSecurity && ['medium', 'high'].includes(activeSecurity.risk_level) ? <label className="tn-python-module__checkbox"><input type="checkbox" checked={riskConfirmed} onChange={(event) => setRiskConfirmed(event.target.checked)} />确认当前扫描结果后允许安装依赖</label> : null}{install.isError ? <ErrorState error={install.error} text="依赖安装失败" /> : null}</section></div><section className="tn-python-module__panel"><div className="tn-python-module__toolbar"><h2 className="tn-python-module__panel-title">运行环境</h2><div className="tn-python-module__actions"><Button secondary pending={create.isPending} onClick={() => create.mutate()}>创建虚拟环境</Button><Button pending={install.isPending} disabled={!environmentQuery.data?.has_requirements || !environmentQuery.data?.python_executable || (['medium', 'high'].includes(activeSecurity?.risk_level ?? '') && !riskConfirmed)} onClick={() => install.mutate()}>安装 requirements</Button><Button secondary pending={rebuild.isPending} onClick={() => rebuild.mutate()}>重建环境</Button><Button secondary pending={removeEnvironment.isPending} onClick={() => { if (window.confirm('确认删除此项目虚拟环境？')) removeEnvironment.mutate() }}>删除环境</Button></div></div><p className="tn-python-module__muted">{environmentQuery.data?.python_executable ?? '尚未创建'} · {environmentQuery.data?.has_requirements ? '检测到 requirements.txt' : '无 requirements.txt'}{environmentQuery.data?.requirements_changed ? ' · 依赖声明已变化' : ''}</p><div className="tn-python-module__actions"><Button secondary pending={installLog.isPending} onClick={() => installLog.mutate()}>查看安装日志</Button><Button secondary pending={clearData.isPending} onClick={() => { if (window.confirm('确认清理项目运行数据？')) clearData.mutate() }}>清理项目数据</Button>{installLog.data ? <span className="tn-python-module__muted">{installLog.data.truncated ? '日志已截断；' : ''}{installLog.data.content || '暂无安装日志。'}</span> : null}</div></section><section className="tn-python-module__columns"><section className="tn-python-module__panel"><div className="tn-python-module__toolbar"><h2 className="tn-python-module__panel-title">项目配置</h2><Button pending={configSave.isPending} disabled={!configQuery.data?.valid} onClick={() => configSave.mutate()}>保存配置</Button></div>{configQuery.isPending ? <LoadingState text="正在读取配置…" /> : configQuery.isError ? <ErrorState error={configQuery.error} text="配置读取失败" /> : <><p className="tn-python-module__muted">{configQuery.data?.file_name ?? 'config.json'}{configQuery.data?.configured_sensitive_paths.length ? ` · 已脱敏 ${configQuery.data.configured_sensitive_paths.length} 项敏感值` : ''}</p><textarea className="tn-python-module__code tn-python-module__code--compact" value={configContent} onChange={(event) => setConfigContent(event.target.value)} /></>}</section><section className="tn-python-module__panel"><div className="tn-python-module__toolbar"><h2 className="tn-python-module__panel-title">版本与存储</h2><Button secondary pending={rollback.isPending} onClick={() => { if (window.confirm('确认回滚到上一版本？')) rollback.mutate() }}>回滚上一版本</Button></div>{storageQuery.data ? <StorageSummary storage={storageQuery.data} /> : <LoadingState text="正在读取存储统计…" />}<div className="tn-python-module__actions"><Button secondary pending={cleanup.isPending && cleanup.variables === 'backups'} onClick={() => cleanup.mutate('backups')}>清理备份</Button><Button secondary pending={cleanup.isPending && cleanup.variables === 'workspaces'} onClick={() => cleanup.mutate('workspaces')}>清理工作区</Button></div>{rollback.isError ? <ErrorState error={rollback.error} text="项目回滚失败" /> : null}</section></section></ModuleShell>
}

function StorageSummary({ storage }: { storage: ProjectStorage }) { return <div className="tn-python-module__summary-list"><div><span>源码</span><strong>{formatBytes(storage.source_size)}</strong></div><div><span>虚拟环境</span><strong>{formatBytes(storage.venv_size)}</strong></div><div><span>运行数据</span><strong>{formatBytes(storage.data_size)}</strong></div><div><span>备份</span><strong>{formatBytes(storage.backup_size)} · {storage.backup_count} 个</strong></div><div><span>总计</span><strong>{formatBytes(storage.total_size)}</strong></div></div> }

function ExecutionsPage() {
  const query = useQuery({ queryKey: ['python-runner', 'executions'], queryFn: listExecutions, refetchInterval: 5_000 })
  const rerun = useMutation({ mutationFn: rerunExecution, onSuccess: () => void query.refetch() })
  const remove = useMutation({ mutationFn: deleteExecution, onSuccess: () => void query.refetch() })
  if (query.isPending) return <ModuleShell title="执行记录" description="查看 Python 脚本的输出、状态和运行历史。"><LoadingState /></ModuleShell>
  if (query.isError) return <ModuleShell title="执行记录" description="查看 Python 脚本的输出、状态和运行历史。"><ErrorState error={query.error} /></ModuleShell>
  return <ModuleShell title="执行记录" description="查看 Python 脚本的输出、状态和运行历史。"><section className="tn-python-module__panel">{query.data.length ? <ExecutionList items={query.data} rerunning={rerun.isPending ? rerun.variables : undefined} deleting={remove.isPending ? remove.variables : undefined} onRerun={(id) => rerun.mutate(id)} onDelete={(id) => { if (window.confirm('确认删除这条执行记录？')) remove.mutate(id) }} /> : <Empty text="还没有执行记录。" />}</section></ModuleShell>
}

function ExecutionDetailPage({ executionId }: { executionId: string }) {
  const query = useQuery({ queryKey: ['python-runner', 'execution', executionId], queryFn: () => getExecution(executionId), refetchInterval: (value) => value.state.data?.status === 'running' ? 2_000 : false })
  const logs = useQuery({ queryKey: ['python-runner', 'execution-logs', executionId], queryFn: () => getExecutionLogs(executionId, undefined, 500), refetchInterval: query.data?.status === 'running' ? 2_000 : false })
  const stop = useMutation({ mutationFn: () => stopExecution(executionId), onSuccess: () => void query.refetch() })
  const rerun = useMutation({ mutationFn: () => rerunExecution(executionId), onSuccess: (next) => runtime?.router.push(`/modules/python-runner/executions/${next.id}`) })
  const remove = useMutation({ mutationFn: () => deleteExecution(executionId), onSuccess: () => runtime?.router.push('/modules/python-runner/executions') })
  if (query.isPending) return <ModuleShell title="执行详情" description="查看执行输出。"><LoadingState /></ModuleShell>
  if (query.isError) return <ModuleShell title="执行详情" description="查看执行输出。"><ErrorState error={query.error} /></ModuleShell>
  const item = query.data
  return <ModuleShell title={item.name} description={`${item.entry_file} · ${formatTime(item.created_at)}`} action={<InternalLink href="/modules/python-runner/executions">返回执行记录</InternalLink>}><section className="tn-python-module__panel"><div className="tn-python-module__toolbar"><div className="tn-python-module__status-line"><Status value={item.status} /><span className="tn-python-module__muted">退出码 {item.exit_code ?? '—'} · {item.duration_ms ?? '—'} ms</span></div><div className="tn-python-module__actions">{item.status === 'running' ? <Button pending={stop.isPending} onClick={() => stop.mutate()}>停止</Button> : <Button secondary pending={rerun.isPending} onClick={() => rerun.mutate()}>重跑</Button>}<Button secondary pending={remove.isPending} onClick={() => { if (window.confirm('确认删除这条执行记录？')) remove.mutate() }}>删除</Button></div></div>{logs.isError ? <ErrorState error={logs.error} text="日志读取失败" /> : <pre className="tn-python-module__output">{logs.data?.map((log) => `[${log.type}] ${log.content}`).join('\n') || item.stdout || item.stderr || '暂无输出'}</pre>}{item.logs_truncated ? <p className="tn-python-module__muted">输出超过上限，较早内容已截断。</p> : null}</section></ModuleShell>
}

interface ScheduleFormState { id?: string; name: string; description: string; sourceType: 'inline' | 'archive'; code: string; projectId: string; entryFile: string; args: string; timeout: number; scheduleType: 'cron' | 'once'; cron: string; runAt: string; timezone: string; enabled: boolean; riskConfirmed: boolean; securityScanId?: string; notificationConfig: NotificationConfig }
const emptyScheduleForm = (): ScheduleFormState => ({ name: '新定时任务', description: '', sourceType: 'inline', code: 'print("scheduled")', projectId: '', entryFile: '', args: '', timeout: 30, scheduleType: 'cron', cron: '*/5 * * * *', runAt: '', timezone: 'Asia/Shanghai', enabled: true, riskConfirmed: false, notificationConfig: defaultNotificationConfig() })

function SchedulesPage() {
  const query = useQuery({ queryKey: ['python-runner', 'schedules'], queryFn: listSchedules, refetchInterval: 10_000 })
  const projects = useQuery({ queryKey: ['python-runner', 'uploads'], queryFn: listUploads, staleTime: 10_000 })
  const [form, setForm] = useState<ScheduleFormState>(emptyScheduleForm)
  const [security, setSecurity] = useState<SecurityScan | null>(null)
  const save = useMutation({ mutationFn: () => saveSchedule(form), onSuccess: () => { setForm(emptyScheduleForm()); setSecurity(null); void query.refetch() }, onError: (error) => { const next = extractSecurity(error); if (next) { setSecurity(next); setForm((current) => ({ ...current, riskConfirmed: false, securityScanId: next.scan_id })) } } })
  const toggle = useMutation({ mutationFn: ({ id, enabled }: { id: string; enabled: boolean }) => toggleSchedule(id, enabled), onSuccess: () => void query.refetch() })
  const run = useMutation({ mutationFn: runSchedule, onSuccess: () => void query.refetch() })
  const remove = useMutation({ mutationFn: deleteSchedule, onSuccess: () => void query.refetch() })
  const edit = (task: ScheduledTask) => { const source = task.source; setForm({ id: task.id, name: task.name, description: task.description, sourceType: source.type, code: source.type === 'inline' ? source.code ?? '' : '', projectId: source.type === 'archive' ? source.project_id ?? source.upload_id ?? '' : '', entryFile: source.type === 'archive' ? source.entry_file ?? '' : '', args: textFromArgs(task.args), timeout: task.timeout_seconds, scheduleType: task.schedule_type as 'cron' | 'once', cron: task.cron_expression ?? '*/5 * * * *', runAt: task.run_at ? task.run_at.slice(0, 16) : '', timezone: task.timezone, enabled: task.enabled, riskConfirmed: false, notificationConfig: task.notification_config ?? defaultNotificationConfig() }); setSecurity(null) }
  if (query.isPending) return <ModuleShell title="定时任务" description="按 Cron 或一次性时间运行 Python。"><LoadingState /></ModuleShell>
  if (query.isError) return <ModuleShell title="定时任务" description="按 Cron 或一次性时间运行 Python。"><ErrorState error={query.error} /></ModuleShell>
  const items = query.data?.items ?? []
  const selectedProject = projects.data?.find((item) => item.id === form.projectId)
  return <ModuleShell title="定时任务" description="按 Cron 或一次性时间运行 Python。"><div className="tn-python-module__columns"><section className="tn-python-module__panel"><h2 className="tn-python-module__panel-title">{form.id ? '编辑定时任务' : '创建定时任务'}</h2><Field label="名称"><input value={form.name} onChange={(event) => setForm((current) => ({ ...current, name: event.target.value }))} /></Field><Field label="执行来源"><select value={form.sourceType} onChange={(event) => setForm((current) => ({ ...current, sourceType: event.target.value as 'inline' | 'archive' }))}><option value="inline">内联代码</option><option value="archive">项目入口</option></select></Field>{form.sourceType === 'inline' ? <Field label="代码"><textarea className="tn-python-module__code tn-python-module__code--compact" value={form.code} onChange={(event) => setForm((current) => ({ ...current, code: event.target.value }))} /></Field> : <><Field label="项目"><select value={form.projectId} onChange={(event) => setForm((current) => ({ ...current, projectId: event.target.value, entryFile: '' }))}><option value="">选择项目</option>{(projects.data ?? []).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></Field><Field label="入口文件"><select value={form.entryFile} onChange={(event) => setForm((current) => ({ ...current, entryFile: event.target.value }))}><option value="">自动选择</option>{(selectedProject?.entry_candidates ?? []).map((item) => <option value={item} key={item}>{item}</option>)}</select></Field></>}<div className="tn-python-module__form-grid"><Field label="调度类型"><select value={form.scheduleType} onChange={(event) => setForm((current) => ({ ...current, scheduleType: event.target.value as 'cron' | 'once' }))}><option value="cron">Cron</option><option value="once">一次性</option></select></Field><Field label="时区"><input value={form.timezone} onChange={(event) => setForm((current) => ({ ...current, timezone: event.target.value }))} /></Field></div>{form.scheduleType === 'cron' ? <Field label="Cron（5 字段）" description="按所选 IANA 时区计算"><input value={form.cron} onChange={(event) => setForm((current) => ({ ...current, cron: event.target.value }))} /></Field> : <Field label="执行时间"><input type="datetime-local" value={form.runAt} onChange={(event) => setForm((current) => ({ ...current, runAt: event.target.value }))} /></Field>}<Field label="命令行参数"><textarea className="tn-python-module__code tn-python-module__code--compact" value={form.args} onChange={(event) => setForm((current) => ({ ...current, args: event.target.value }))} /></Field><SecurityConfirmation scan={security} checked={form.riskConfirmed} onChange={(value) => setForm((current) => ({ ...current, riskConfirmed: value }))} /><NotificationFields value={form.notificationConfig} onChange={(notificationConfig) => setForm((current) => ({ ...current, notificationConfig }))} /><div className="tn-python-module__actions"><Button pending={save.isPending} onClick={() => save.mutate()}>{form.id ? '保存任务' : '创建任务'}</Button>{form.id ? <Button secondary onClick={() => setForm(emptyScheduleForm())}>取消编辑</Button> : null}</div>{save.isError ? <ErrorState error={save.error} text="定时任务保存失败" /> : null}</section><section className="tn-python-module__panel"><h2 className="tn-python-module__panel-title">已配置任务</h2>{items.length ? <ul className="tn-python-module__list">{items.map((task) => <li className="tn-python-module__list-item" key={task.id}><div><strong>{task.name}</strong><div className="tn-python-module__muted">{task.schedule_type === 'cron' ? task.cron_expression : formatTime(task.run_at)} · {task.timezone} · 下次 {formatTime(task.next_run_at)}</div></div><div className="tn-python-module__actions"><Status value={task.enabled ? 'enabled' : 'disabled'} /><Button secondary pending={toggle.isPending && toggle.variables?.id === task.id} onClick={() => toggle.mutate({ id: task.id, enabled: !task.enabled })}>{task.enabled ? '停用' : '启用'}</Button><Button secondary pending={run.isPending && run.variables === task.id} onClick={() => run.mutate(task.id)}>运行</Button><Button secondary onClick={() => edit(task)}>编辑</Button><Button secondary pending={remove.isPending && remove.variables === task.id} onClick={() => { if (window.confirm('确认删除此定时任务？')) remove.mutate(task.id) }}>删除</Button></div></li>)}</ul> : <Empty text="还没有定时任务。" />}</section></div></ModuleShell>
}

function saveSchedule(form: ScheduleFormState) {
  const source: ExecutionSource = form.sourceType === 'inline' ? { type: 'inline', code: form.code } : { type: 'archive', project_id: form.projectId, entry_file: form.entryFile }
  const payload = { name: form.name, description: form.description, source, args: argsFromText(form.args), timeout_seconds: form.timeout, schedule_type: form.scheduleType, cron_expression: form.scheduleType === 'cron' ? form.cron : null, run_at: form.scheduleType === 'once' ? new Date(form.runAt).toISOString() : null, timezone: form.timezone, enabled: form.enabled, notification_config: form.notificationConfig, security: form.riskConfirmed && form.securityScanId ? { risk_confirmed: true, scan_id: form.securityScanId } : undefined }
  return form.id ? updateSchedule(form.id, payload) : createSchedule(payload)
}

function PersistentPage() {
  const query = useQuery({ queryKey: ['python-runner', 'persistent'], queryFn: listPersistentTasks, refetchInterval: 5_000 })
  const projects = useQuery({ queryKey: ['python-runner', 'uploads'], queryFn: listUploads, staleTime: 10_000 })
  const emptyForm = () => ({ id: '', name: '新常驻任务', description: '', projectId: '', entryFile: '', args: '', runtime: 'project_venv', autoStart: false, restartPolicy: 'never', restartDelay: 5, maxRestart: 3, notificationConfig: defaultNotificationConfig() })
  const [form, setForm] = useState(emptyForm)
  const [selected, setSelected] = useState<string | null>(null)
  const save = useMutation({ mutationFn: () => { const source: ExecutionSource = { type: 'archive', project_id: form.projectId, entry_file: form.entryFile }; const payload = { name: form.name, description: form.description, source, args: argsFromText(form.args), runtime_environment: form.runtime, auto_start: form.autoStart, restart_policy: form.restartPolicy, restart_delay_seconds: form.restartDelay, max_restart_count: form.maxRestart, notification_config: form.notificationConfig }; return form.id ? updatePersistentTask(form.id, payload) : createPersistentTask(payload) }, onSuccess: () => { setForm(emptyForm()); void query.refetch() } })
  const start = useMutation({ mutationFn: startPersistent, onSuccess: () => void query.refetch() })
  const stop = useMutation({ mutationFn: stopPersistent, onSuccess: () => void query.refetch() })
  const restart = useMutation({ mutationFn: restartPersistent, onSuccess: () => void query.refetch() })
  const remove = useMutation({ mutationFn: deletePersistent, onSuccess: () => void query.refetch() })
  const logs = useQuery({ queryKey: ['python-runner', 'persistent-logs', selected], queryFn: () => getPersistentLogs(selected ?? ''), enabled: Boolean(selected), refetchInterval: 3_000 })
  const events = useQuery({ queryKey: ['python-runner', 'persistent-events', selected], queryFn: () => getPersistentEvents(selected ?? ''), enabled: Boolean(selected) })
  const clearLogs = useMutation({ mutationFn: () => clearPersistentLogs(selected ?? ''), onSuccess: () => void logs.refetch() })
  if (query.isPending) return <ModuleShell title="常驻任务" description="管理长期运行的 Python 进程和重启策略。"><LoadingState /></ModuleShell>
  if (query.isError) return <ModuleShell title="常驻任务" description="管理长期运行的 Python 进程和重启策略。"><ErrorState error={query.error} /></ModuleShell>
  const items = query.data?.items ?? []
  const project = projects.data?.find((item) => item.id === form.projectId)
  const selectedTask = items.find((item) => item.id === selected)
  const edit = (task: PersistentTask) => { const source = task.source.type === 'archive' ? task.source : null; setForm({ id: task.id, name: task.name, description: task.description, projectId: source?.project_id ?? source?.upload_id ?? '', entryFile: source?.entry_file ?? '', args: textFromArgs(task.args), runtime: task.runtime_environment, autoStart: task.auto_start, restartPolicy: task.restart_policy, restartDelay: task.restart_delay_seconds, maxRestart: task.max_restart_count, notificationConfig: task.notification_config ?? defaultNotificationConfig() }); setSelected(task.id) }
  return <ModuleShell title="常驻任务" description="管理长期运行的 Python 进程和重启策略。"><div className="tn-python-module__columns"><section className="tn-python-module__panel"><h2 className="tn-python-module__panel-title">{form.id ? '编辑常驻任务' : '创建常驻任务'}</h2><Field label="名称"><input value={form.name} onChange={(event) => setForm((current) => ({ ...current, name: event.target.value }))} /></Field><Field label="项目"><select value={form.projectId} onChange={(event) => setForm((current) => ({ ...current, projectId: event.target.value, entryFile: '' }))}><option value="">选择项目</option>{(projects.data ?? []).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></Field><Field label="入口文件"><select value={form.entryFile} onChange={(event) => setForm((current) => ({ ...current, entryFile: event.target.value }))}><option value="">自动选择</option>{(project?.entry_candidates ?? []).map((item) => <option value={item} key={item}>{item}</option>)}</select></Field><Field label="命令行参数"><textarea className="tn-python-module__code tn-python-module__code--compact" value={form.args} onChange={(event) => setForm((current) => ({ ...current, args: event.target.value }))} /></Field><div className="tn-python-module__form-grid"><Field label="运行环境"><select value={form.runtime} onChange={(event) => setForm((current) => ({ ...current, runtime: event.target.value }))}><option value="project_venv">项目虚拟环境</option><option value="auto">自动选择</option><option value="system">系统 Python</option></select></Field><Field label="重启策略"><select value={form.restartPolicy} onChange={(event) => setForm((current) => ({ ...current, restartPolicy: event.target.value }))}><option value="never">从不</option><option value="on_failure">失败时</option><option value="always">总是</option></select></Field></div><div className="tn-python-module__form-grid"><Field label="重启间隔（秒）"><input type="number" min={0} max={3600} value={form.restartDelay} onChange={(event) => setForm((current) => ({ ...current, restartDelay: Number(event.target.value) }))} /></Field><Field label="最大重启次数"><input type="number" min={0} max={100} value={form.maxRestart} onChange={(event) => setForm((current) => ({ ...current, maxRestart: Number(event.target.value) }))} /></Field></div><label className="tn-python-module__checkbox"><input type="checkbox" checked={form.autoStart} onChange={(event) => setForm((current) => ({ ...current, autoStart: event.target.checked }))} />模块进程启动后自动启动</label><NotificationFields value={form.notificationConfig} onChange={(notificationConfig) => setForm((current) => ({ ...current, notificationConfig }))} persistent /><div className="tn-python-module__actions"><Button pending={save.isPending} disabled={!form.projectId} onClick={() => save.mutate()}>{form.id ? '保存任务' : '创建任务'}</Button>{form.id ? <Button secondary onClick={() => setForm(emptyForm())}>取消编辑</Button> : null}</div>{save.isError ? <ErrorState error={save.error} text="常驻任务保存失败" /> : null}</section><section className="tn-python-module__panel"><h2 className="tn-python-module__panel-title">已配置任务</h2>{items.length ? <ul className="tn-python-module__list">{items.map((task) => <li className="tn-python-module__list-item" key={task.id}><div><button className="tn-python-module__file-button" type="button" onClick={() => setSelected(task.id)}><strong>{task.name}</strong></button><div className="tn-python-module__muted">{task.source.type === 'archive' ? task.source.entry_file ?? '自动入口' : '内联任务'} · {task.restart_policy} · 重启 {task.restart_count}/{task.max_restart_count}</div></div><div className="tn-python-module__actions"><Status value={task.status} />{task.status === 'running' ? <Button secondary pending={stop.isPending && stop.variables === task.id} onClick={() => stop.mutate(task.id)}>停止</Button> : <Button pending={start.isPending && start.variables === task.id} onClick={() => start.mutate(task.id)}>启动</Button>}{task.status === 'running' ? <Button secondary pending={restart.isPending && restart.variables === task.id} onClick={() => restart.mutate(task.id)}>重启</Button> : null}<Button secondary onClick={() => edit(task)}>编辑</Button><Button secondary pending={remove.isPending && remove.variables === task.id} onClick={() => { if (window.confirm('确认删除此常驻任务？')) remove.mutate(task.id) }}>删除</Button></div></li>)}</ul> : <Empty text="还没有常驻任务，请先从项目创建。" />}</section></div>{selectedTask ? <section className="tn-python-module__columns"><section className="tn-python-module__panel"><div className="tn-python-module__toolbar"><h2 className="tn-python-module__panel-title">{selectedTask.name} · 日志</h2><Button secondary pending={clearLogs.isPending} onClick={() => clearLogs.mutate()}>清理日志</Button></div>{logs.isPending ? <LoadingState text="正在读取常驻任务日志…" /> : <pre className="tn-python-module__output">{logs.data?.lines.join('\n') || '暂无输出'}</pre>}</section><section className="tn-python-module__panel"><h2 className="tn-python-module__panel-title">生命周期事件</h2>{events.data?.length ? <ul className="tn-python-module__list">{events.data.map((event) => <li className="tn-python-module__list-item" key={event.id}><span>{event.message}</span><span className="tn-python-module__muted">{formatTime(event.created_at)}</span></li>)}</ul> : <Empty text="暂无生命周期事件。" />}</section></section> : null}</ModuleShell>
}

function route(path: string, render: (props: ToolNestModuleRouteRenderProps) => ReactNode) { return { key: `python-runner:${path || 'index'}`, path, render } }
const module: ToolNestReactFrontendModule = { id: 'python-runner', version: '2.0.0', layout: { content: 'padded' }, install(context) { runtime = context; setPythonRunnerApi(context.apiClient); context.registerMenus([{ key: 'python-runner', label: 'Python 工具', path: '', icon: 'code', order: 20, children: [{ key: 'python-runner-overview', label: '总览', path: '', icon: 'home' }, { key: 'python-runner-run', label: '快速运行', path: 'run', icon: 'run' }, { key: 'python-runner-projects', label: '项目仓库', path: 'projects', icon: 'cube' }, { key: 'python-runner-executions', label: '执行记录', path: 'executions', icon: 'history' }, { key: 'python-runner-schedules', label: '定时任务', path: 'schedules', icon: 'schedule' }, { key: 'python-runner-persistent', label: '常驻任务', path: 'persistent', icon: 'task' }] }]); context.registerRoutes([route('', () => <OverviewPage />), route('run', ({ query }) => <RunPage initialProjectId={query.project} />), route('projects', () => <ProjectsPage />), route('projects/:projectId', ({ params }) => <ProjectDetailPage projectId={params.projectId ?? ''} />), route('executions', () => <ExecutionsPage />), route('executions/:executionId', ({ params }) => <ExecutionDetailPage executionId={params.executionId ?? ''} />), route('schedules', () => <SchedulesPage />), route('persistent', () => <PersistentPage />)]); context.onDispose(() => { runtime = undefined; setPythonRunnerApi(null) }) } }
export default module
